{
  "title": "Ukrainian expats discuss language requirements, job search, salaries, and relocation preferences",
  "topics": [
    {
      "id": "expatriates",
      "title": "Ukrainian expatriates in Slovakia, Austria and Poland",
      "claims": [
        {
          "text": "@AndriiRaccoon lives in Austria",
          "evidence": [3]
        },
        {
          "text": "walternet134 lives in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 has at least two acquaintances living abroad",
          "evidence": [12]
        },
        {
          "text": "One of P3's acquaintances arrived recently, another has been there for several years",
          "evidence": [13]
        },
        {
          "text": "P3 has been living in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P1 has been living in Slovakia for almost a year",
          "evidence": [43]
        },
        {
          "text": "P1 started living (or moved) on 03.09.2025",
          "evidence": [54]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements for jobs and daily life",
      "claims": [
        {
          "text": "The primary language spoken in Austria is German",
          "evidence": [14]
        },
        {
          "text": "English can be used with some people in Austria",
          "evidence": [15]
        },
        {
          "text": "Approximately 95% of job postings require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Recruiters often filter out candidates who lack local language skills",
          "evidence": [27]
        },
        {
          "text": "Some employers still hire candidates with little or no local language knowledge",
          "evidence": [29]
        },
        {
          "text": "Companies commonly request B2 level language proficiency, sometimes accept B1, and usually do not require a certificate",
          "evidence": [46]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        },
        {
          "text": "In everyday situations, English feels awkward for speakers, creating a language barrier",
          "evidence": [51]
        },
        {
          "text": "At international events English works fine, but everyday life in Austria can be difficult without the local language",
          "evidence": [55]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Job search experiences, application rates and salaries",
      "claims": [
        {
          "text": "It took P3 about two months to find a job abroad",
          "evidence": [17]
        },
        {
          "text": "P3 sent roughly 100 job applications and received only three interview invitations",
          "evidence": [21]
        },
        {
          "text": "The highest conversion in the hiring process in Austria is from vacancy to interview",
          "evidence": [20]
        },
        {
          "text": "Salaries in Europe are generally higher than in Ukraine",
          "evidence": [35]
        },
        {
          "text": "P3’s salary was above the minimum wage (higher than a McDonald’s wage) but still a minimal salary",
          "evidence": [37]
        },
        {
          "text": "P3 applied to any position that did not list German language requirements",
          "evidence": [36]
        },
        {
          "text": "P3 needed to find a job before 04.03 and started working on 02.03",
          "evidence": [39, 41]
        },
        {
          "text": "The working language in P3’s job is English",
          "evidence": [44]
        },
        {
          "text": "Improving language skills would allow applying to more positions with greater confidence",
          "evidence": [42]
        }
      ]
    },
    {
      "id": "language-learning",
      "title": "Personal language learning efforts and resources",
      "claims": [
        {
          "text": "P3 started learning the local language recently because of discomfort in daily interactions",
          "evidence": [47]
        },
        {
          "text": "Self‑reported B2 level is considered sufficient for most jobs, and a certificate is usually not required",
          "evidence": [46]
        },
        {
          "text": "P1 suggests joining Discord channels to practice English conversation",
          "evidence": [56, 57]
        }
      ]
    },
    {
      "id": "relocation-preferences",
      "title": "Preferences and considerations for staying in Austria and other countries",
      "claims": [
        {
          "text": "P3 considers Austria the best choice among European countries for personal relocation",
          "evidence": [60]
        },
        {
          "text": "P3 has also considered Ireland, Norway, and Spain as possible destinations",
          "evidence": [60]
        },
        {
          "text": "P3’s boyfriend has lived in Austria for over 10 years and is not optimistic about the country's future",
          "evidence": [60]
        },
        {
          "text": "P3 is interested in attending a tech event in Warsaw",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
